using System;using System.Collections.Generic;using RimWorld;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class CycloneEvolution {
  public const string DefName="EH_CycloneAscendant";
  public static bool Active(Pawn p){return CycloneVfx.HasLineage(p);}
  public static bool Wind(Pawn p){if(p==null||p.health==null)return false;foreach(var h in p.health.hediffSet.hediffs)if(h.def.defName=="EH_WindHeart")return true;return false;}
  public static HediffComp_CycloneMastery Mastery(Pawn p){if(p==null||p.health==null)return null;foreach(var h in p.health.hediffSet.hediffs){var c=h.TryGetComp<HediffComp_CycloneMastery>();if(c!=null)return c;}return null;}
  public static string Problem(Pawn p){var c=Mastery(p);if(c==null||!Wind(p))return "Requires ordinary Wind ascension.";if(!AzureRules.Ready(c.kills,c.parent.ageTicks))return "Requires 150 unique hostile non-animal kills and ten Wind Ascendant days.";var wind=HediffComp_WindAbilities.On(p);if(!ElementalTeaching.Ready(p)||ElementalTeachingSession.Busy(p)||ElementalAnimationBridge.Controlled(p)||HediffComp_ElementalTransform.Transforming(p)||AzureEvolution.Evolving(p)||wind!=null&&wind.Busy)return "Finish the current technique, lesson or transformation first.";return null;}
  public static bool Upgrade(Pawn p){if(p==null||p.health==null)return false;HediffWithComps root=null;foreach(var h in p.health.hediffSet.hediffs)if(h.def.defName=="EH_WindHeart")root=h as HediffWithComps;if(root==null)return Active(p);AzureLineage.Rebind(root,DefDatabase<HediffDef>.GetNamed(DefName));p.health.Notify_HediffChanged(root);var transform=root.TryGetComp<HediffComp_ElementalTransform>();if(transform!=null)transform.RebuildAzureKit();if(p.Spawned)foreach(var comp in root.comps)comp.Notify_Spawned();return true;}
  public static bool Complete(Pawn p){var c=Mastery(p);if(c==null||!Wind(p)||!AzureRules.Ready(c.kills,c.parent.ageTicks)||!ElementalTeaching.Ready(p))return false;if(!Upgrade(p))return false;p.Drawer.renderer.SetAllGraphicsDirty();ElementalAudio.Ability(p,ElementalSound.Impact);Messages.Message(p.LabelShort+" has evolved into a Cyclone Ascendant!",p,MessageTypeDefOf.PositiveEvent,false);return true;}
  public static readonly string[] Names={"Vacuum Draw","Skyward Gale","Cyclone Reversal","Heaven-Rending Tempest"};
  public static readonly string[] Details={"Dash through a clear lane up to twelve cells, cutting each eligible victim once. Requires a free exit; walls and unsafe landings block the route.","Two rising cuts lift a surviving enemy briefly in emerald wind ribbons, then grant Gale Guard. Airbound control has a shared target-side recovery window.","Watch the selected opponent for an ordinary melee attack or dodge, deflect it, sidestep and sweep back. A bounded local sweep strikes each secondary once; the primary is excluded.","Three deliberate cuts with safe flanking footwork, ending in a heavy emerald slash. Automatic combos can spend their remaining strikes on nearby hostiles; manual casts keep the selected target. Each cut commits once."};
 }
 public sealed class HediffCompProperties_CycloneMastery:HediffCompProperties {public HediffCompProperties_CycloneMastery(){compClass=typeof(HediffComp_CycloneMastery);}}
 public sealed class HediffComp_CycloneMastery:HediffComp {
  public int kills;HashSet<int> victims=new HashSet<int>();int nextHalo;
  public override void CompExposeData(){Scribe_Values.Look(ref kills,"EH_cycloneMasteryKills");Scribe_Collections.Look(ref victims,"EH_cycloneMasteryVictims",LookMode.Value);if(victims==null)victims=new HashSet<int>();}
  public override void Notify_KilledPawn(Pawn victim,DamageInfo? info){if(CycloneEvolution.Active(Pawn)||victim==null||!AzureRules.CountKill(victim.HostileTo(Pawn),victim.RaceProps.Animal,victim==Pawn)||!victims.Add(victim.thingIDNumber))return;kills++;}
  public override void Notify_Spawned(){if(CycloneEvolution.Active(Pawn))CycloneVfx.TrackHalo(Pawn);}
  public override void CompPostTickInterval(ref float adjustment,int delta){if(!Pawn.Spawned)return;int now=Find.TickManager.TicksGame;if(Pawn.CurJobDef==DefDatabase<JobDef>.GetNamed("EH_EvolveCyclone"))EvolutionCinematic.Track(Pawn);if(CycloneEvolution.Active(Pawn)&&now>=nextHalo){nextHalo=now+60;CycloneVfx.TrackHalo(Pawn);}}
  public override void CompPostPostRemoved(){CycloneVfx.Forget(Pawn);}
  public override string CompTipStringExtra{get{return CycloneEvolution.Active(Pawn)?"Cyclone evolution complete.":"Cyclone mastery: "+kills+" / 150 unique hostile non-animal kills; "+(parent.ageTicks/60000f).ToString("0.0")+" / 10 Ascendant days.";}}
  public override IEnumerable<Gizmo> CompGetGizmos(){if(!ElementalCombatPolicy.Controlled(Pawn)||CycloneEvolution.Active(Pawn))yield break;var command=new Command_Action{defaultLabel="Evolve: Cyclone",defaultDesc=CompTipStringExtra+"\nAn interruptible 4.5-second wind coronation grants five Cyclone techniques, helmetless royal regalia, an emerald sword, a subtle head halo and evolved defense. No resource cost. Interrupted rituals keep readiness.",icon=CycloneVfx.Icon(5),groupable=false,action=()=>{if(CycloneEvolution.Problem(Pawn)==null)Pawn.jobs.TryTakeOrderedJob(JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed("EH_EvolveCyclone"),Pawn),JobTag.Misc);}};var reason=CycloneEvolution.Problem(Pawn);if(reason!=null)command.Disable(reason);yield return command;if(DebugSettings.godMode)yield return new DevEvolutionReadyCommand{isEligible=()=>CycloneEvolution.Wind(Pawn)&&CycloneEvolution.Mastery(Pawn)==this,defaultLabel="DEV: Evolution-Ready",defaultDesc="God Mode only. Unlock Cyclone milestones; press Evolve: Cyclone to perform the ritual.",icon=CycloneVfx.Icon(5),groupable=false,action=()=>{if(DebugSettings.godMode){kills=Math.Max(kills,150);parent.ageTicks=Math.Max(parent.ageTicks,600000);}}};}
 }
 public sealed class ThoughtWorker_CycloneResolve:ThoughtWorker_Hediff {protected override ThoughtState CurrentStateInternal(Pawn p){return CycloneEvolution.Active(p)?ThoughtState.ActiveAtStage(1):base.CurrentStateInternal(p);}}
}
